<?php
/** Real MySQL print provenance/eligibility; no bank transmission or registration. */
require __DIR__.'/banco_brasil_open_batches_mysql.php';
require_once APP_MODULES_PATH.'banco_brasil/libraries/BancoBrasil/CnabBoleto.php';
$syntheticAgreement=new \BancoBrasil\Agreement(new \BancoBrasil\Scope(1,2,'001:00452-3:000000123873-X','sandbox','1234567'),'12ABC34501DE35','EMPRESA SINTETICA','019');
$codes=\BancoBrasil\CnabBoleto::codes($syntheticAgreement,'1234567890','2025-02-22','100.01');
essentialCheck($codes['barcode']==='00192100000000100010000001234567123456789017','seven-digit agreement fixed synthetic vector and reset factor');
essentialCheck(strlen($codes['line'])===47&&preg_replace('/[^0-9]/','',$codes['formatted_line'])===$codes['line'],'formatted line preserves exactly47 digits');
essentialCheck(substr(\BancoBrasil\CnabBoleto::codes($syntheticAgreement,'1','2025-02-23','0.01')['barcode'],5,14)==='10010000000001','next day and one cent retain exact positions');
essentialCheck(substr(\BancoBrasil\CnabBoleto::codes($syntheticAgreement,'1','2049-10-13','99999999.99')['barcode'],5,14)==='99999999999999','maximum supported factor and amount');
essentialThrows(fn()=>\BancoBrasil\CnabBoleto::codes($syntheticAgreement,'1','2025-02-21','1.00'),'bb_boleto_date_unsupported','old factor cycle cannot be guessed');
essentialThrows(fn()=>\BancoBrasil\CnabBoleto::codes($syntheticAgreement,'1','2049-10-14','1.00'),'bb_boleto_date_unsupported','next factor cycle requires explicit support');
essentialThrows(fn()=>\BancoBrasil\CnabBoleto::codes($syntheticAgreement,'1','2026-11-06','0.00'),'bb_boleto_amount_invalid','zero amount is not a payable invoice');
essentialThrows(fn()=>\BancoBrasil\CnabBoleto::codes($syntheticAgreement,'00000000000','2026-11-06','1.00'),'bb_boleto_number_invalid','invalid sequence rejected');
$printInvoice=$s->create($a,7,$input,hash('sha256','print-invoice'));
$printBatch=$bank->generate($a,7,$connection,$binding,'2026-10-22',[array_replace($title,['invoice_id'=>$printInvoice])],hash('sha256','print-batch'));
$beforePrint=static function()use($db,$p):array{$out=[];foreach(['bb_batches','bb_origins','bb_number_reservations','bb_batch_requests','bb_batch_actions','bb_audit','invoicepaymentrecords','invoices'] as $table)$out[$table]=$db->query('SELECT * FROM '.$p.$table)->result_array();return $out;};
$before=$beforePrint();$boleto=$bank->boleto($a,7,$printBatch,$printInvoice);
essentialCheck($beforePrint()===$before,'printing preserves batch/origin/number counters/receipts/native invoices and all operation markers');
essentialCheck($boleto['bank_state']==='generated_registration_not_confirmed'&&$boleto['environment']==='sandbox','print does not claim bank registration');
essentialCheck($bank->boleto($a,7,$printBatch,$printInvoice)===$boleto,'repeat print is deterministic before download');
essentialThrows(fn()=>$bank->boleto($b,7,$printBatch,$printInvoice),'bb_batch_unavailable','foreign company cannot print batch');
essentialThrows(fn()=>$bank->boleto($a,999,$printBatch,$printInvoice),'bb_origination_access_denied','unknown actor cannot print');
essentialThrows(fn()=>$bank->boleto($a,7,$printBatch,$groupOne),'bb_boleto_unavailable','invoice from another batch cannot be substituted');
$db->query('UPDATE '.$p.'invoices SET total=total+1 WHERE id=?',[$printInvoice]);
essentialThrows(fn()=>$bank->boleto($a,7,$printBatch,$printInvoice),'bb_boleto_unavailable','changed amount cannot print old payment instructions');
$db->query('UPDATE '.$p.'invoices SET total=? WHERE id=?',[$boleto['snapshot']['invoice']['total'],$printInvoice]);
$db->query("UPDATE {$p}staff SET active=0 WHERE staffid=7");
essentialThrows(fn()=>$bank->boleto($a,7,$printBatch,$printInvoice),'bb_origination_access_denied','revoked actor cannot print a previously accessible boleto');
$db->query("UPDATE {$p}staff SET active=1 WHERE staffid=7");
$printBytes=$bank->download($a,7,$printBatch);
essentialCheck($bank->boleto($a,7,$printBatch,$printInvoice)===$boleto,'first remittance download does not change instrument');
essentialCheck($bank->download($a,7,$printBatch)===$printBytes,'printing does not alter frozen remittance bytes');
$db->query('UPDATE '.$p.'invoices SET status=5 WHERE id=?',[$printInvoice]);
essentialThrows(fn()=>$bank->boleto($a,7,$printBatch,$printInvoice),'bb_boleto_unavailable','cancelled invoice cannot print payable document');
$db->query('UPDATE '.$p.'invoices SET status=? WHERE id=?',[$boleto['snapshot']['invoice']['status'],$printInvoice]);
$boleto['barcode_svg']=\BancoBrasil\CnabBoleto::svg($boleto['barcode']);
essentialCheck(!str_contains($boleto['barcode_svg'],'DOCTYPE')&&str_contains($boleto['barcode_svg'],'viewBox='),'SVG scales all barcode bars without an external DTD');
ob_start();require APP_MODULES_PATH.'banco_brasil/views/cnab_boleto.php';$html=ob_get_clean();
essentialCheck(str_contains($html,'HOMOLOGAÇÃO — NÃO PAGAR')&&str_contains($html,'<svg')&&str_contains($html,$boleto['formatted_line']),'real print view contains test status, I25 and exact line');
if(getenv('BB_BOLETO_HTML'))file_put_contents(getenv('BB_BOLETO_HTML'),$html);
echo 'CNAB240 printable instrument: '.$GLOBALS['essentialChecks'].' cumulative MySQL checks passed; no bank validation.'.PHP_EOL;
